#include <iostream>
#include <regex>
#include <string>

std::string markdownToHtml(const std::string& markdown) {
    std::string html = markdown;
    std::regex re(R"(^#\s*([0-9]+)\s*([a-zA-Z0-9_]+)");
    std::smatch matches;
    while (std::regex_search(html, matches, re)) {
        html = html.replace(matches.position(), matches.length(), "<h" + matches[1] + ">" + matches[2] + "</h" + matches[1] + ">");
    }
    return html;
}
```

